class Book {
  #id = 1;

  static has(value) {
    return #id in value;
  }

  static read(value) {
    return value.#id;
  }
}

class Film {
  #id = 1;
}

console.log(Book.has(new Book()));
console.log(Book.has(new Film()));
console.log(Book.has(Book));
try {
  console.log(Book.read(new Film()));
} catch (error) {
  console.log(error.name);
}
console.log(Book.read(new Book()));
